export class UnicodeEncodeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'UnicodeEncodeError';
  }
}

function formatOffendingCharacter(codePoint) {
  const hex = codePoint.toString(16);

  if (codePoint <= 0xff) {
    return `\\x${hex.padStart(2, '0')}`;
  }

  if (codePoint <= 0xffff) {
    return `\\u${hex.padStart(4, '0')}`;
  }

  return `\\U${hex.padStart(8, '0')}`;
}

export function encodeAscii(text) {
  let position = 0;

  for (const character of text) {
    const codePoint = character.codePointAt(0);

    if (codePoint > 0x7f) {
      throw new UnicodeEncodeError(
        `'ascii' codec can't encode character '${formatOffendingCharacter(codePoint)}' in position ${position}: ordinal not in range(128)`,
      );
    }

    position += 1;
  }

  return new ByteString(text);
}

