import { isByteString } from './byte_string.mjs';

function chooseQuote(raw) {
  return raw.includes("'") && !raw.includes('"') ? '"' : "'";
}

function escapeByte(code, quote) {
  if (code === 0x5c) {
    return '\\\\';
  }

  if (code === quote.charCodeAt(0)) {
    return `\\${quote}`;
  }

  if (code === 0x09) {
    return '\\t';
  }

  if (code === 0x0a) {
    return '\\n';
  }

  if (code === 0x0d) {
    return '\\r';
  }

  if (code >= 0x20 && code <= 0x7e) {
    return String.fromCharCode(code);
  }

  return `\\x${code.toString(16).padStart(2, '0')}`;
}

export function bytesRepr(byteString) {
  const raw = byteString.raw;
  const quote = chooseQuote(raw);
  let escaped = '';

  for (let index = 0; index < raw.length; index += 1) {
    escaped += escapeByte(raw.charCodeAt(index), quote);
  }

  return `b${quote}${escaped}${quote}`;
}

export function repr(value) {
  if (isByteString(value)) {
    return bytesRepr(value);
  }

  if (typeof value === 'bigint') {
    return value.toString();
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => repr(item)).join(', ')}]`;
  }

  if (value instanceof Map) {
    const items = Array.from(
      value.entries(),
      ([key, item]) => `${repr(key)}: ${repr(item)}`,
    );

    return `{${items.join(', ')}}`;
  }

  throw new TypeError(`Unsupported value type: ${typeof value}`);
}

