  return `usage: ${scriptName} [-h] --a A --b B --c C`;
}

function buildHelp(scriptName) {
  return `${buildUsage(scriptName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n`;
}

function throwCliError(scriptName, message) {
  throw new CliExit(
    2,
    '',
    `${buildUsage(scriptName)}\n${scriptName}: error: ${message}\n`,
  );
}

function parseOptionToken(token) {
  if (token === '--a' || token.startsWith('--a=')) {
    return {
      optionName: 'a',
      inlineValue: token === '--a' ? null : token.slice(4),
    };
  }

  if (token === '--b' || token.startsWith('--b=')) {
    return {
      optionName: 'b',
      inlineValue: token === '--b' ? null : token.slice(4),
    };
  }

  if (token === '--c' || token.startsWith('--c=')) {
    return {
      optionName: 'c',
      inlineValue: token === '--c' ? null : token.slice(4),
    };
  }

  return null;
}

function canConsumeSeparatedValue(token) {
  if (token === undefined) {
    return false;
  }

  if (token === '-') {
    return true;
  }

  if (!token.startsWith('-')) {
    return true;
  }

  return NEGATIVE_NUMBER_TOKEN.test(token);
}

